# build adjacency with sorted time lists
adj=collections.defaultdict(lambda: collections.defaultdict(list))
for u,v,t in events:
    adj[u][v].append(t); adj[v][u].append(t)

def closures(lo,hi,delta=800):
    res=[]
    for u,v,t in events:
        if not (lo<=t<=hi): continue
        # common neighbors
        nu=adj[u]; nv=adj[v]
        small,large=(nu,nv) if len(nu)<len(nv) else (nv,nu)
        for c in small:
            if c in large and c!=u and c!=v:
                # latest support times before t
                a=[x for x in nu[c] if x<t]
                b=[x for x in nv[c] if x<t]
                if a and b:
                    m=max(max(a),max(b))
                    if t-m<=delta:
                        res.append((u,v,t,c,m,t-m))
    return res

