def cand_cl(lo,hi,delta):
    out=[]
    for u,v,t in events:
        if not(lo<=t<=hi): continue
        nu,nv=adj[u],adj[v]
        s,l=(nu,nv) if len(nu)<len(nv) else (nv,nu)
        for c in s:
            if c in l and c!=u and c!=v and (u in cs or v in cs or c in cs):
